select case when age >= 60 then 'high' when age >= 37 then 'mid' else 'low' end as age_bucket, date_trunc('MONTH', signup_date) as signup_month, max(age) - min(age) as age_range, avg(age) as avg_age from customers where not (credit_limit between 7400 and 11500 and lower(trim(email)) = 'bob.smith@yahoo.com') group by case when age >= 60 then 'high' when age >= 37 then 'mid' else 'low' end, date_trunc('MONTH', signup_date) having sum(case when country = 'TH' then 1 else 0 end) >= 24 order by age_bucket asc, signup_month asc limit 5;
